import atcoder/extra/numeric/float256

proc checkHex(
    word3, word2, word1, word0: uint64;
    expected: string,
) =
  let value = fromBits(word3, word2, word1, word0)
  let actual = toHexString(value)
  doAssert actual == expected
  doAssert actual.len == 66
  var reparsed: Float256
  doAssert tryParseHexFloat256(actual, reparsed)
  doAssert sameBits(value, reparsed)

proc checkDecimalRoundtrip(value: Float256; text: string) =
  var reparsed: Float256
  doAssert tryParseFloat256(text, reparsed)
  if isNaN(value):
    doAssert isNaN(reparsed)
    doAssert signBit(value) == signBit(reparsed)
    doAssert isQuietNaN(reparsed)
  else:
    doAssert sameBits(value, reparsed)

proc checkScientific(
    word3, word2, word1, word0: uint64;
    expected: string,
) =
  let value = fromBits(word3, word2, word1, word0)
  let actual = toScientificString(value)
  doAssert actual == expected
  checkDecimalRoundtrip(value, actual)

proc checkShortest(
    word3, word2, word1, word0: uint64;
    expected: string,
) =
  let value = fromBits(word3, word2, word1, word0)
  let actual = toShortestString(value)
  doAssert actual == expected
  checkDecimalRoundtrip(value, actual)

